-- Confirm-Open step for ID (PROJECT_PLAN §6.4.1/§6.13, decisions #30/#31; TODO Track 2).
-- GENERATED by scripts/etl/gen_confirm_open.sh id — edit the generator, not this file.
-- "GREEN must be earned": where PAD-US says open (GREEN) but the authoritative ID ownership
-- layer (Idaho SMA © Idaho Dept of Lands) shows NO public land within ~100m, the open status is unconfirmed -> YELLOW.
-- Buffer-carve (Utah pattern): parcels the source maps as NOT-public (private/tribal/water/null)
-- are carved back out of the buffer so adjacency never blankets a known-not-public parcel.
-- Prereq: staging.sma_id loaded (scripts/etl/pull_sma.sh id); legality_polygons built (unify.sql).
-- Idempotent: deletes prior idl_id rows first.
--
-- TARGET TABLE (review PP-8): reads and writes go to the psql variable :legality_tbl, defaulting
-- to the live tiles.legality_polygons. rebuild_legality.sh passes tiles.legality_polygons_new so
-- the whole sequence builds off to the side and reaches live only via atomic_swap after gating.
SET client_min_messages TO WARNING;

\if :{?legality_tbl}
\else
  \set legality_tbl tiles.legality_polygons
\endif

DELETE FROM :legality_tbl WHERE source_key = 'idl_id';

DROP TABLE IF EXISTS staging.conf_notpub_id;
-- SubDivide the not-public side too: wall-to-wall states (CO) have thousands of large private
-- multipolygons, and un-subdivided carve unions OOM-crashed the dev Postgres (2026-07-12).
-- Small pieces keep every LATERAL union local and bounded.
CREATE TABLE staging.conf_notpub_id AS
  SELECT ST_SubDivide(ST_MakeValid(geom), 512) AS geom FROM staging.sma_id
  -- NOT TRUE, not NOT(...): for a row whose ownership attribute is NULL the predicate is NULL,
  -- and NOT(NULL) is NULL, so plain NOT silently dropped every unknown-ownership parcel from the
  -- carve — the exact rows the design says must be carved (review finding PP-5; confirm_open_ut.sql
  -- got this right with 'owner IS NULL OR owner NOT IN (...)', the generator did not). NULL/unknown
  -- ownership must never confirm open (docs/planning/PROJECT_PLAN.md:2359).
  WHERE (upper(mgmt_agncy) IN ('BLM','USFS','NPS','NWR','BOR','COE','LU_DOI','LU_USDA')) IS NOT TRUE;
-- PARCEL-GRADE CARVE (Tier-1 validation finding, 2026-07-12): SMA sources are GCDB/PLSS-grade
-- and miss parcel-sized private inholdings inside blocks they map federal — the validation
-- caught 9 real false-GREENs in CO/NM cabin/ranch country. Where county parcel data is loaded
-- (staging.parcels), assessor-confirmed private parcels join the carve, giving those counties
-- Utah-grade resolution. No-op where staging.parcels is absent or has no rows for the state.
INSERT INTO staging.conf_notpub_id
  SELECT ST_SubDivide(ST_MakeValid(geom), 512)
  FROM staging.parcels
  WHERE to_regclass('staging.parcels') IS NOT NULL
    -- Review finding PP-32. Was owner_class='private', which meant state/county/city/tribal
    -- parcels — public but NOT open — silently confirmed that PAD-US's GREEN was open, and left
    -- 'unknown' (doubt) unprotected too. Only affirmatively FEDERAL ownership supports an open
    -- reading, so everything else is carved.
    -- Written as an explicit IN rather than <> 'federal' so it degrades correctly against
    -- pre-PP-32 data: a staging.parcels built before the four-class split has no 'federal' rows,
    -- and <> 'federal' would then match its old catch-all 'public' class and over-carve genuinely
    -- public ground. The IN list simply matches less until the parcels are re-pulled.
    AND state = 'ID' AND owner_class IN ('private','other_public','unknown');
CREATE INDEX conf_notpub_id_gix ON staging.conf_notpub_id USING GIST (geom);

-- NON-OPEN PUBLIC (review finding PP-2): state trust / state park / wildlife / county / military
-- ground. It is public, so it is NOT private — but it does not confirm that PAD-US's GREEN is
-- open, because collecting there needs a permit or is prohibited outright. These codes used to
-- live in the public predicate, which is why the app served "Managing agency BLM — generally
-- open" over Utah State Trust land, Colorado State Land Board sections, NM State Trust and DOD,
-- and Idaho endowment land. Kept as its own layer so the demotion can say WHY, instead of
-- mislabelling state land "possibly private".
DROP TABLE IF EXISTS staging.conf_nonopen_id;
CREATE TABLE staging.conf_nonopen_id AS
  SELECT ST_SubDivide(ST_MakeValid(geom), 512) AS geom FROM staging.sma_id
  WHERE (upper(mgmt_agncy) IN ('STATE','STATEFG','STATEPR','STATEOTH','MIL')) IS TRUE;
CREATE INDEX conf_nonopen_id_gix ON staging.conf_nonopen_id USING GIST (geom);

DROP TABLE IF EXISTS staging.conf_buf_id;
CREATE TABLE staging.conf_buf_id AS
  SELECT ST_CollectionExtract(ST_MakeValid(ST_Difference(b.geom,
           COALESCE(np.geom, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326)))), 3) AS geom
  FROM (SELECT ST_Transform(ST_Buffer(ST_Transform(ST_SubDivide(ST_MakeValid(geom), 512), 5070), 100), 4326) AS geom
        FROM staging.sma_id
        WHERE upper(mgmt_agncy) IN ('BLM','USFS','NPS','NWR','BOR','COE','LU_DOI','LU_USDA')) b
  LEFT JOIN LATERAL (
    SELECT ST_Union(n.geom) AS geom FROM staging.conf_notpub_id n WHERE ST_Intersects(n.geom, b.geom)
  ) np ON true;
CREATE INDEX conf_buf_id_gix ON staging.conf_buf_id USING GIST (geom);

INSERT INTO :legality_tbl
  (geom, verdict, reason, land_manager, unit_nm, protection_status, state_nm, data_vintage, source_key)
SELECT ST_Multi(d.geom), 'YELLOW',
  CASE WHEN d.nonopen_m2 > 400
    THEN 'State trust / state park / military land per ID ownership data (Idaho SMA © Idaho Dept of Lands) — permit or closure likely; ownership sources conflict. Verify before collecting.'
    ELSE 'Open status not confirmed by ID public-ownership data (Idaho SMA © Idaho Dept of Lands) — possibly private; verify before collecting.'
  END,
  NULL, NULL, 'unconfirmed-open', 'ID', 'IDL SMA (republished 2026-07-07) (confirm-open vs PAD-US)', 'idl_id'
FROM (
  SELECT frag.geom,
         -- overlap with affirmatively-not-public ground (drives the sliver exemption below)
         COALESCE((SELECT ST_Area(ST_Intersection(frag.geom, ST_Union(np.geom))::geography)
                   FROM staging.conf_notpub_id np WHERE ST_Intersects(np.geom, frag.geom)), 0) AS notpub_m2,
         -- overlap with public-but-not-open ground (drives which reason the user is shown)
         COALESCE((SELECT ST_Area(ST_Intersection(frag.geom, ST_Union(no.geom))::geography)
                   FROM staging.conf_nonopen_id no WHERE ST_Intersects(no.geom, frag.geom)), 0) AS nonopen_m2,
         -- PP-36. Size of the SOURCE polygon this fragment came off, not the fragment. See the
         -- filter below for why the distinction is the whole point.
         COALESCE((SELECT max(ST_Area(np.geom::geography))
                   FROM staging.conf_notpub_id np WHERE ST_Intersects(np.geom, frag.geom)), 0) AS notpub_src_m2,
         COALESCE((SELECT max(ST_Area(no.geom::geography))
                   FROM staging.conf_nonopen_id no WHERE ST_Intersects(no.geom, frag.geom)), 0) AS nonopen_src_m2
  FROM (
    SELECT (ST_Dump(
              ST_CollectionExtract(
                ST_MakeValid(ST_Difference(g.geom,
                  COALESCE(b.buf, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326)))), 3))).geom AS geom
    FROM (SELECT ST_Subdivide(geom, 256) AS geom FROM :legality_tbl
          WHERE state_nm='ID' AND verdict='GREEN' AND source_key='padus') g
    LEFT JOIN LATERAL (
      SELECT ST_Union(cb.geom) AS buf FROM staging.conf_buf_id cb WHERE ST_DWithin(cb.geom, g.geom, 0.003)
    ) b ON true
  ) frag
  WHERE frag.geom IS NOT NULL AND NOT ST_IsEmpty(frag.geom)
) d
-- SLIVER FILTER (review findings PP-1 / PP-18). The 1000 m² threshold exists to drop
-- registration noise where two sources roughly agree on a boundary. Applied to raw ST_Dump
-- fragments it did something else: the 100 m buffer erodes a private parcel from every edge and
-- the ST_Subdivide(...,256) chunk lines cut what is left, so a large private block survives only
-- as crumbs — and every crumb under the threshold was discarded, leaving live GREEN over mapped
-- private land. Measured on this data: a 2,624,031 m² NV parcel mapped PVT reduced to an 882 m²
-- fragment and dropped.
-- A fragment overlapping ground an authoritative source affirmatively maps as NOT public is not
-- noise, it is the signal. Such fragments are kept down to the project's own documented
-- "meaningful parcel" floor of 400 m² (docs/planning/PROJECT_PLAN.md:2374, "recorded not hidden") rather than
-- the coarser per-state sliver threshold. Below that floor both are boundary artifacts.
-- Deliberately asymmetric: extra YELLOW is safe, missing YELLOW is not.
--
-- PP-36. The three tests above all measure the FRAGMENT, and lowering the threshold (PP-1/PP-18
-- took it 1000 -> 400 for notpub-overlapping pieces) only moved the edge; the BASIS was the bug.
-- Subdivide chunk lines and buffer edges cut a large private parcel into pieces, and a piece can
-- measure less than the floor while the parcel it belongs to is enormous. Measured on ID
-- (42.031603, -115.564597): a 366 m² fragment whose notpub_m2 was also 366 — failing both
-- ST_Area > 1000 and notpub_m2 > 400 — carved off a parcel of 667,003 m² that sma_id maps
-- PRIVATE. It was dropped, and the app served GREEN there.
--
-- This is also exactly why gate_notpublic_green.sh disagreed with the carve and the residuals
-- looked unexplained: the gate selects SOURCE polygons >= 400 m², so it judges the parcel while
-- the carve judged the fragment. Same number, different subject.
--
-- So: keep a fragment when the ground it sits on clears the floor, however small the fragment.
-- Can only ADD yellow, never remove it.
--
-- CAVEAT: conf_notpub_/conf_nonopen_ hold ST_SubDivide(...,512) pieces, so notpub_src_m2 is the
-- area of a PIECE of the parcel, not the whole parcel. Still vastly coarser than the fragment and
-- it fixes the measured cases; doing it exactly would need the pre-subdivide area carried through
-- as a column.
WHERE ST_Area(d.geom::geography) > 1000
   OR d.notpub_m2  > 400
   OR d.nonopen_m2 > 400
   OR d.notpub_src_m2  > 400
   OR d.nonopen_src_m2 > 400;

SELECT count(*) AS unconfirmed_polys, round((sum(ST_Area(geom::geography))/1e6)::numeric, 2) AS km2
FROM :legality_tbl WHERE source_key = 'idl_id';
